<div class="page-heading"><div><h1>Control de lotes</h1><p>Existencias y trazabilidad por fecha de vencimiento</p></div><?php if(\App\Core\Auth::isAdmin()):?><a class="btn btn-primary" href="<?=url('index.php?page=lote-form')?>"><i class="bi bi-plus-lg"></i> Nuevo lote</a><?php endif?></div>
<div class="panel mb-4"><form class="row g-2"><input type="hidden" name="page" value="lotes"><div class="col-md-10"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Buscar lote, medicamento o código"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Buscar</button></div></form></div>
<div class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Lote</th><th>Medicamento</th><th>Ingreso</th><th>Vencimiento</th><th>Inicial</th><th>Disponible</th><th>Condición</th><th></th></tr></thead><tbody><?php foreach($lotes as$l):$cond=$l['dias']<=0?'Vencido':($l['dias']<=30?'Próximo':'Vigente');$color=$l['dias']<=0?'danger':($l['dias']<=30?'warning':'success');?><tr><td><span class="code-chip"><?=e($l['numero_lote'])?></span></td><td><strong><?=e($l['nombre'])?></strong><small class="d-block text-muted"><?=e($l['codigo'])?></small></td><td><?=date('d/m/Y',strtotime($l['fecha_ingreso']))?></td><td><?=date('d/m/Y',strtotime($l['fecha_vencimiento']))?><small class="d-block text-muted"><?=$l['dias']?> días</small></td><td><?=$l['cantidad_inicial']?></td><td class="fw-bold"><?=$l['cantidad_disponible']?></td><td><span class="badge text-bg-<?=$color?>"><?=$cond?></span><?php if($l['estado']==='bloqueado'):?><span class="badge text-bg-dark">Bloqueado</span><?php endif?></td><td><?php if(\App\Core\Auth::isAdmin()):?><form method="post" action="<?=url('index.php?page=lote-toggle')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn btn-sm btn-light" data-confirm="¿Cambiar bloqueo del lote?"><i class="bi bi-lock"></i></button></form><?php endif?></td></tr><?php endforeach?><?php if(!$lotes):?><tr><td colspan="8" class="empty-state">No hay lotes registrados</td></tr><?php endif?></tbody></table></div></div>
